{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Dapagliflozin, the closest structural analogue (Morgan similarity 0.4853), has an absolute oral bioavailability of 78% (90% CI 73-83%) in healthy subjects after a 10 mg oral dose versus an IV microdose, directly supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Tofogliflozin, a same-class SGLT2 inhibitor with a similar diaryl and sugar-like scaffold, has a mean absolute oral bioavailability of 97.5% in healthy volunteers, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Empagliflozin, another close SGLT2 inhibitor analogue, shows oral bioavailability greater than 60% in healthy subjects (reported up to 78-90%), supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Bexagliflozin, a related SGLT2 inhibitor with a similar glucose-derived polar core, has an absolute oral bioavailability of about 78% in humans, reinforcing the high-bioavailability pattern for this structural family.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close structural analogue of dapagliflozin and other SGLT2 inhibitors, all of which show high absolute oral bioavailability in humans (78% for dapagliflozin, 97.5% for tofogliflozin, >60-90% for empagliflozin, ~78% for bexagliflozin). The consistent human data strongly support F >= 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query molecule.",
    "The cyclic ether modification in the sugar-like portion may alter metabolic stability or permeability relative to the tested analogues.",
    "Fasted-state-specific pharmacokinetic data for the query are not directly available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

